var age = Math.max(0, +v('age') || 0), life = Math.max(age + 0.1, +v('life') || 1);
var pct = Math.min(100, age / life * 100);
var total = Math.max(1, Math.round(life * 52)), left = Math.min(total, Math.round((life - age) * 52));
Crowd.units(el, { total: total, used: total - left, unit: '週',
title: '人生を1週ずつ玉にすると',
final: function (l) { return '人生の ' + Math.round(pct) + '% が過ぎて、のこりは約 ' + l.toLocaleString('ja-JP') + '週。今週も、その1つです。'; } });
